// Recipes contain no owned packet fields or aggregate drop path.
struct SiteRecipe {
    key: Key,
    packets: &'static [fn() -> Packet],
    copy_output: Option<usize>,
}

#[inline(never)]
fn materialize_sites(recipes: &[SiteRecipe]) -> Vec<Site> {
    let mut sites = Vec::with_capacity(recipes.len());
    for recipe in recipes {
        let mut packets = Vec::with_capacity(recipe.packets.len());
        for factory in recipe.packets {
            packets.push(factory());
        }
        sites.push(Site {
            key: recipe.key,
            packets,
            copy_output: recipe.copy_output,
        });
    }
    sites
}

