#[inline(never)]
fn qwen2b_sites() -> Vec<Site> {
    materialize_sites(QWEN2B_SITES)
}
pub(crate) fn metadata_bytes(profile: FullModelProfile) -> Result<usize> {
    let n = match profile {
        FullModelProfile::Qwen08 => 39845888,
        FullModelProfile::Qwen2B => 34603008,
    };
    if n == 0 {
        Err(Error::Unsupported(
            "short-HF complete captured catalogue absent".into(),
        ))
    } else {
        Ok(n)
    }
}
pub(crate) fn sites(profile: FullModelProfile) -> Result<Vec<Site>> {
    metadata_bytes(profile)?;
    Ok(match profile {
        FullModelProfile::Qwen08 => qwen08_sites(),
        FullModelProfile::Qwen2B => qwen2b_sites(),
    })
}
const QWEN08_PRIVATE: &[(Role, usize)] = &[
    (Role::Lse, 32),
    (Role::Lse, 1504),
    (Role::Lse, 1824),
    (Role::Lse, 1984),
    (Role::Lse, 2144),
    (Role::Lse, 2304),
    (Role::PrivateO, 4096),
    (Role::PartialO, 16384),
    (Role::PartialLse, 64),
];
const QWEN2B_PRIVATE: &[(Role, usize)] = &[
    (Role::Lse, 32),
    (Role::Lse, 1504),
    (Role::Lse, 1824),
    (Role::Lse, 1984),
    (Role::Lse, 2144),
    (Role::Lse, 2304),
    (Role::PrivateO, 4096),
    (Role::PartialO, 16384),
    (Role::PartialLse, 64),
];
pub(crate) fn private_layout(profile: FullModelProfile) -> Result<&'static [(Role, usize)]> {
    metadata_bytes(profile)?;
    Ok(match profile {
        FullModelProfile::Qwen08 => QWEN08_PRIVATE,
        FullModelProfile::Qwen2B => QWEN2B_PRIVATE,
    })
}
